document.function:

{ def history, def field_value_history, def field ->
	def value = stringifyValue(field)
	def lastValue = field_value_history.options[field.importId]
	def language = org.springframework.context.i18n.LocaleContextHolder.getLocale().getLanguage()
	def field_name = field.name.getTranslation(language)
	addToHistory(history, "changed field " + wrapElement(field_name as String, "b") + " value [" + lastValue + "] -> [" + value + "]", false)
}


{ def history, def text, boolean appendLine ->
	def loggedUser = userService.getLoggedOrSystem()
	def nowTime = java.time.LocalDateTime.now()
	def nowTimeFormated = nowTime.format("dd.MM.yyyy HH:mm:ss")
	def newText
	if (!appendLine) {
		newText = "\r[" + nowTimeFormated + "] " + wrapElement(loggedUser.fullName, "b") + ": " + text
	} else {
		newText = " " + text
	}
	change history value { history.value + newText }
}


{ def history, def description ->
	addToHistory(history, description, false)
}


{ def history, def taskTitle, def taskEventVerb ->
	return addWorkflowEventToHistory(history, taskEventVerb + " task " + taskTitle)
}


{ info_warnings ->
	def result = ["sk":"<p style=\"font-size:16px;\"><b>Upozornenia</b><p><br>", "en":"<p style=\"font-size:16px;\"><b>Warnings</b><p><br>"]
	def language = org.springframework.context.i18n.LocaleContextHolder.getLocale().getLanguage()
	def fieldIds = ["info_sums", "info_search"]
	def collectedValues = fieldIds.collect { fieldId -> useCase.dataSet[fieldId].value }.findAll { it?.trim() }
	if (collectedValues) {
		change info_warnings value { result[language] + collectedValues.join("<br><br>") }
		make info_warnings,visible on transitions when { true }
	} else {
		change info_warnings value { null }
		make info_warnings,hidden on transitions when { true }
	}
}


{ Double number, int scale ->
       return (BigDecimal.valueOf(number).scale() > scale)
}


{ search_ico, odberatel_select, odberatel_select_cache ->
	subjects = loadSubjectFromOrsr(search_ico, odberatel_select, odberatel_select_cache)
	if (!subjects) {
		return
	}
	change odberatel_select options { subjects }
	if (subjects && subjects.size() == 1) {
		change odberatel_select value { odberatel_select.options.keySet()[0] }
	}
}


{ search_ico, odberatel_select, odberatel_select_cache ->
	try {
		if (search_ico.value) {
			def subject = orsr(byIco, search_ico.value)
			if (!subject) {
				return [:]
			}
			def address = "$subject.street $subject.streetNumber, $subject.city, $subject.postalCode" as String
			change odberatel_select_cache options { [(subject.id): (subject.name + ";#;" + address + ";#;" + "SK")] }
			return [(subject.id): (subject.id + ", " + subject.name)]
		}
	} catch (Exception e) {
		log.error("Failed to reach ORSR for $search_ico.value", e)
	}
	return [:]
}


{ pdf, page_preview, pdf_image_pages, page_preview_index ->
	if (pdf_image_pages.options[(page_preview_index.value as int) as String]) {
		change page_preview value { renderImageToHtml(pdf_image_pages.options[(page_preview_index.value as int) as String] as String) }
		return
	}
	def imageFileValue = generateFileFieldValue(useCase, "pdf_image_pages", pdf.value.name + "_" + page_preview_index.value)
	def file = pdfToPngService.renderPage(new java.io.File(pdf.value.path), page_preview_index.value as int, imageFileValue.path, 640)
	def newOptions = [((page_preview_index.value as int) as String):(file.path), *:(pdf_image_pages.options)]
	change page_preview value { renderImageToHtml(file.path) }
	change pdf_image_pages options { newOptions }
}


{ String pattern = "#.##", Double number ->
       if (number) {
          def df = new java.text.DecimalFormat(pattern)
          df.setRoundingMode(java.math.RoundingMode.HALF_UP)
          return Double.parseDouble(df.format(number).replace(",", "."))
       }
       return number
    }


{ field ->
	if (hasScaleBiggerThan(field.value, 2)) {
		change field value { roundDouble("#.##", field.value) }
		return
	}
}


{ polozky_suma_rozdiel, info_sums ->
def language = org.springframework.context.i18n.LocaleContextHolder.getLocale().getLanguage()
	if (polozky_suma_rozdiel.value > 0) {
		if(language == "sk"){
			change info_sums value { """<p><span style="color: red;">❗ Hodnota položiek je nižšia ako hodnota faktúry</span></p>""" }
		} else {
			change info_sums value { """<p><span style="color: red;">❗ The value of the items is lower than the value of the invoice</span></p>""" }
		}
	}
	else if (polozky_suma_rozdiel.value < 0) {
		if(language == "sk"){
			change info_sums value { """<p><span style="color: red;">❗ Hodnota položiek je vyššia ako hodnota faktúry</span></p>""" }
		} else{
		change info_sums value { """<p><span style="color: red;">❗ The value of the items is higher than the value of the invoice</span></p>""" }
		}
	}
}

