	return
}
def polozky = polozky_taskRef.value.collect { tsk ->
	def caseId = findTask { (it._id.eq(tsk)) }?.caseId
	if (caseId) {
		return findCaseElastic(caseId)
	}
	return null
}.findAll { it }
