polozky.each {
	workflowService.deleteCase(it)
}


polozky_taskRef: f.polozky_taskRef,
polozky_suma: f.polozky_suma;
if (!polozky_taskRef.value) {
	return
}
def polozky = polozky_taskRef.value.collect { tsk -> findCase(findTask { (it._id.eq(tsk)) }.caseId) }
		.findAll { it.processIdentifier == "polozka" }
def reducedPolozky = polozky.findAll { !it.dataSet["is_marked"].value }
def toDeletePolozky = polozky.findAll { it.dataSet["is_marked"].value }
def totalNumber = 0
reducedPolozky.each { pr ->
	totalNumber += (pr.getFieldValue("celkom_cena_dph") ?: 0)
}
change polozky_suma value { totalNumber }
roundFieldToTwoDecimal(polozky_suma)
def delValues = toDeletePolozky.collect { it.tasks.find { it.transition == "t1" }?.task }
change polozky_taskRef value { polozky_taskRef.value.findAll { !(it in delValues) } }
toDeletePolozky.each {
	workflowService.deleteCase(it)
}


